/* Red Dot Pharmacy - Navy Blue Glassmorphism Design System */

/* ============================================
   CSS VARIABLES - Design Tokens
   ============================================ */
:root {
    /* Primary Colors - Navy Blue */
    --primary: #1e3a5f;
    --primary-dark: #0f2744;
    --primary-light: #e8f0f8;
    --primary-glow: rgba(30, 58, 95, 0.15);
    --primary-accent: #2563eb;
    --primary-accent-light: #3b82f6;

    /* Legacy naming for compatibility */
    --primary-red: #1e3a5f;
    --primary-red-dark: #0f2744;
    --primary-red-light: #e8f0f8;
    --primary-red-glow: rgba(30, 58, 95, 0.15);

    /* Neutral Colors */
    --gray-50: #f8fafc;
    --gray-100: #f1f5f9;
    --gray-200: #e2e8f0;
    --gray-300: #cbd5e1;
    --gray-400: #94a3b8;
    --gray-500: #64748b;
    --gray-600: #475569;
    --gray-700: #334155;
    --gray-800: #1e293b;
    --gray-900: #0f172a;

    /* Accent Colors */
    --success: #10b981;
    --success-light: #d1fae5;
    --info: #0ea5e9;
    --info-light: #e0f2fe;
    --warning: #f59e0b;
    --warning-light: #fef3c7;
    --danger: #ef4444;
    --danger-light: #fee2e2;

    /* Glass Effects */
    --glass-bg: rgba(255, 255, 255, 0.7);
    --glass-bg-dark: rgba(30, 58, 95, 0.85);
    --glass-border: rgba(255, 255, 255, 0.3);
    --glass-shadow: 0 8px 32px rgba(30, 58, 95, 0.15);

    /* Gradients */
    --gradient-primary: linear-gradient(135deg, #1e3a5f 0%, #0f2744 100%);
    --gradient-accent: linear-gradient(135deg, #2563eb 0%, #1e3a5f 100%);
    --gradient-hero: linear-gradient(135deg, #f8fafc 0%, #e8f0f8 50%, #f1f5f9 100%);
    --gradient-dark: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
    --gradient-glass: linear-gradient(135deg, rgba(255,255,255,0.9) 0%, rgba(255,255,255,0.6) 100%);
    --gradient-glass-dark: linear-gradient(135deg, rgba(30,58,95,0.95) 0%, rgba(15,39,68,0.9) 100%);
    --gradient-mesh: radial-gradient(at 40% 20%, rgba(37, 99, 235, 0.15) 0px, transparent 50%),
                     radial-gradient(at 80% 0%, rgba(30, 58, 95, 0.1) 0px, transparent 50%),
                     radial-gradient(at 0% 50%, rgba(37, 99, 235, 0.08) 0px, transparent 50%);

    /* Shadows */
    --shadow-xs: 0 1px 2px rgba(15, 23, 42, 0.04);
    --shadow-sm: 0 2px 4px rgba(15, 23, 42, 0.06);
    --shadow-md: 0 4px 12px rgba(15, 23, 42, 0.08);
    --shadow-lg: 0 8px 24px rgba(15, 23, 42, 0.12);
    --shadow-xl: 0 16px 48px rgba(15, 23, 42, 0.16);
    --shadow-primary: 0 8px 24px rgba(30, 58, 95, 0.25);
    --shadow-red: 0 8px 24px rgba(30, 58, 95, 0.25);
    --shadow-hover: 0 12px 32px rgba(30, 58, 95, 0.18);
    --shadow-glow: 0 0 40px rgba(37, 99, 235, 0.15);

    /* Border Radius */
    --radius-sm: 8px;
    --radius-md: 12px;
    --radius-lg: 16px;
    --radius-xl: 24px;
    --radius-2xl: 32px;
    --radius-full: 9999px;

    /* Spacing */
    --section-padding: 100px;
    --section-padding-mobile: 60px;

    /* Typography */
    --font-primary: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    --font-display: 'Poppins', 'Inter', sans-serif;

    /* Transitions */
    --transition-fast: 0.15s ease;
    --transition-base: 0.25s ease;
    --transition-slow: 0.4s ease;
    --transition-bounce: 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* ============================================
   BASE STYLES
   ============================================ */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-primary);
    font-size: 16px;
    line-height: 1.7;
    color: var(--gray-800);
    background-color: #FFFFFF;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

.main-content {
    padding-top: 80px;
    min-height: 100vh;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-display);
    font-weight: 700;
    line-height: 1.3;
    color: var(--gray-900);
}

.display-4 {
    font-weight: 800;
    letter-spacing: -0.02em;
}

.lead {
    font-size: 1.125rem;
    font-weight: 400;
    color: var(--gray-600);
}

/* ============================================
   BRANDING & UTILITY CLASSES
   ============================================ */
.bg-red-dot {
    background: var(--gradient-primary) !important;
}

.text-red-dot {
    color: var(--primary-red) !important;
}

.text-gradient {
    background: var(--gradient-primary);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

/* Section Titles */
.section-badge {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 8px 20px;
    background: var(--primary-red-light);
    color: var(--primary-red);
    border-radius: var(--radius-full);
    font-size: 0.875rem;
    font-weight: 600;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    margin-bottom: 16px;
}

.section-title {
    font-size: 2.75rem;
    font-weight: 800;
    margin-bottom: 16px;
    color: var(--gray-900);
}

.section-subtitle {
    font-size: 1.125rem;
    color: var(--gray-600);
    max-width: 600px;
    margin: 0 auto;
}

/* ============================================
   BUTTONS
   ============================================ */
.btn {
    font-family: var(--font-primary);
    font-weight: 600;
    padding: 12px 28px;
    border-radius: var(--radius-md);
    transition: all var(--transition-base);
    border: none;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
}

.btn-red-dot,
.btn-danger {
    background: var(--gradient-primary);
    color: white;
    box-shadow: var(--shadow-sm);
}

.btn-red-dot:hover,
.btn-danger:hover {
    transform: translateY(-2px);
    box-shadow: var(--shadow-red);
    color: white;
}

.btn-red-dot:active,
.btn-danger:active {
    transform: translateY(0);
}

.btn-outline-danger {
    background: transparent;
    color: var(--primary-red);
    border: 2px solid var(--primary-red);
}

.btn-outline-danger:hover {
    background: var(--primary-red);
    color: white;
    transform: translateY(-2px);
    box-shadow: var(--shadow-red);
}

.btn-lg {
    padding: 16px 36px;
    font-size: 1.0625rem;
    border-radius: var(--radius-lg);
}

.btn-success {
    background: linear-gradient(135deg, #43A047 0%, #2E7D32 100%);
    border: none;
    color: white;
}

.btn-success:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 24px rgba(67, 160, 71, 0.3);
    color: white;
}

/* ============================================
   NAVIGATION
   ============================================ */
.navbar {
    padding: 16px 0;
    transition: all var(--transition-base);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
}

.navbar.scrolled {
    padding: 12px 0;
    box-shadow: var(--shadow-md);
}

.navbar-brand {
    font-family: var(--font-display);
    font-size: 1.5rem;
    font-weight: 800;
    display: flex;
    align-items: center;
    gap: 10px;
}

.navbar-brand i {
    font-size: 1.25rem;
}

.navbar-nav .nav-link {
    font-weight: 500;
    padding: 8px 16px !important;
    color: rgba(255, 255, 255, 0.9) !important;
    transition: all var(--transition-base);
    border-radius: var(--radius-sm);
}

.navbar-nav .nav-link:hover {
    color: white !important;
    background: rgba(255, 255, 255, 0.1);
}

/* ============================================
   HERO SECTION
   ============================================ */
.hero-section {
    background: var(--gradient-hero);
    position: relative;
    overflow: hidden;
    padding: 40px 0 80px;
}

.hero-section::before {
    content: '';
    position: absolute;
    top: -50%;
    right: -20%;
    width: 800px;
    height: 800px;
    background: radial-gradient(circle, rgba(37, 99, 235, 0.12) 0%, transparent 70%);
    pointer-events: none;
    animation: pulse-glow 8s ease-in-out infinite;
}

.hero-section::after {
    content: '';
    position: absolute;
    bottom: -30%;
    left: -10%;
    width: 600px;
    height: 600px;
    background: radial-gradient(circle, rgba(30, 58, 95, 0.1) 0%, transparent 70%);
    pointer-events: none;
    animation: pulse-glow 10s ease-in-out infinite reverse;
}

@keyframes pulse-glow {
    0%, 100% { opacity: 0.6; transform: scale(1); }
    50% { opacity: 1; transform: scale(1.1); }
}

.hero-content {
    position: relative;
    z-index: 1;
}

.hero-content h1 {
    font-size: 3.5rem;
    font-weight: 800;
    line-height: 1.15;
    margin-bottom: 24px;
    color: var(--gray-900);
}

.hero-content h1 span {
    background: var(--gradient-primary);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.hero-content .lead {
    font-size: 1.25rem;
    color: var(--gray-600);
    margin-bottom: 32px;
    max-width: 540px;
}

.hero-buttons {
    display: flex;
    flex-wrap: wrap;
    gap: 16px;
    margin-bottom: 48px;
}

.hero-buttons .btn {
    padding: 16px 32px;
    font-size: 1rem;
}

/* Hero Stats */
.hero-stats {
    display: flex;
    gap: 40px;
    padding-top: 32px;
    border-top: 1px solid var(--gray-200);
}

.stat-item {
    text-align: center;
}

.stat-item h3 {
    font-size: 2.5rem;
    font-weight: 800;
    color: var(--primary-red);
    margin-bottom: 4px;
    line-height: 1;
}

.stat-item small {
    font-size: 0.875rem;
    color: var(--gray-500);
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

/* Hero Image */
.hero-image {
    position: relative;
    z-index: 1;
}

.hero-image img {
    border-radius: var(--radius-xl);
    box-shadow: var(--shadow-xl);
    transition: transform var(--transition-slow);
}

.hero-image:hover img {
    transform: scale(1.02);
}

/* Floating Badge on Hero Image */
.hero-image::before {
    content: '🏥 Trusted Healthcare';
    position: absolute;
    top: 20px;
    left: -20px;
    background: white;
    padding: 12px 20px;
    border-radius: var(--radius-full);
    box-shadow: var(--shadow-lg);
    font-size: 0.875rem;
    font-weight: 600;
    color: var(--gray-800);
    z-index: 2;
    animation: float 3s ease-in-out infinite;
}

@keyframes float {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-10px); }
}

/* ============================================
   SERVICES SECTION
   ============================================ */
.services-section {
    padding: 80px 0;
    background: white;
}

.service-card {
    background: var(--glass-bg);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    padding: 40px 32px;
    border-radius: var(--radius-lg);
    text-align: center;
    transition: all var(--transition-base);
    border: 1px solid var(--glass-border);
    height: 100%;
    position: relative;
    overflow: hidden;
    box-shadow: var(--glass-shadow);
}

.service-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 4px;
    background: var(--gradient-accent);
    transform: scaleX(0);
    transition: transform var(--transition-base);
}

.service-card:hover {
    transform: translateY(-8px);
    box-shadow: var(--shadow-lg), var(--shadow-glow);
    border-color: rgba(37, 99, 235, 0.3);
    background: rgba(255, 255, 255, 0.85);
}

.service-card:hover::before {
    transform: scaleX(1);
}

.service-icon {
    width: 80px;
    height: 80px;
    margin: 0 auto 24px;
    background: var(--primary-red-light);
    border-radius: var(--radius-lg);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2rem;
    color: var(--primary-red);
    transition: all var(--transition-base);
}

.service-card:hover .service-icon {
    background: var(--gradient-primary);
    color: white;
    transform: scale(1.1);
}

.service-card h5 {
    font-size: 1.25rem;
    font-weight: 700;
    margin-bottom: 12px;
    color: var(--gray-900);
}

.service-card p {
    color: var(--gray-600);
    margin: 0;
    font-size: 0.9375rem;
    line-height: 1.6;
}

/* ============================================
   MEDICINE STORE SECTION
   ============================================ */
.medicine-section {
    padding: var(--section-padding) 0;
    background: var(--gray-50);
}

.medicine-header {
    text-align: center;
    margin-bottom: 48px;
}

/* Feature Highlights */
.feature-highlights {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 24px;
    margin-bottom: 48px;
}

.feature-highlight {
    background: var(--glass-bg);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    padding: 24px;
    border-radius: var(--radius-md);
    text-align: center;
    transition: all var(--transition-base);
    border: 1px solid var(--glass-border);
    box-shadow: var(--glass-shadow);
}

.feature-highlight:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-md), var(--shadow-glow);
    border-color: rgba(37, 99, 235, 0.3);
    background: rgba(255, 255, 255, 0.85);
}

.feature-highlight i {
    font-size: 1.75rem;
    color: var(--primary-red);
    margin-bottom: 12px;
}

.feature-highlight h6 {
    font-size: 0.9375rem;
    font-weight: 600;
    color: var(--gray-800);
    margin-bottom: 4px;
}

.feature-highlight small {
    color: var(--gray-500);
    font-size: 0.8125rem;
}

/* Search Form */
.search-form {
    max-width: 600px;
    margin: 0 auto 32px;
}

.search-form .input-group {
    background: white;
    border-radius: var(--radius-full);
    box-shadow: var(--shadow-md);
    overflow: hidden;
    border: 2px solid transparent;
    transition: all var(--transition-base);
}

.search-form .input-group:focus-within {
    border-color: var(--primary-red);
    box-shadow: var(--shadow-lg), 0 0 0 4px var(--primary-red-glow);
}

.search-form .form-control {
    border: none;
    padding: 16px 24px;
    font-size: 1rem;
}

.search-form .form-control:focus {
    box-shadow: none;
}

.search-form .btn {
    border-radius: 0 var(--radius-full) var(--radius-full) 0;
    padding: 16px 28px;
}

/* Category Filter */
.category-filter {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 12px;
    margin-bottom: 40px;
}

.category-filter .btn {
    padding: 10px 24px;
    border-radius: var(--radius-full);
    font-weight: 500;
    font-size: 0.9375rem;
    border: 2px solid var(--gray-300);
    background: white;
    color: var(--gray-700);
    transition: all var(--transition-base);
}

.category-filter .btn:hover {
    border-color: var(--primary-red);
    color: var(--primary-red);
    background: var(--primary-red-light);
}

.category-filter .btn.active {
    background: var(--gradient-primary);
    border-color: var(--primary-red);
    color: white;
    box-shadow: var(--shadow-red);
}

/* Medicine Cards */
.medicine-card {
    background: var(--glass-bg);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border-radius: var(--radius-lg);
    overflow: hidden;
    box-shadow: var(--glass-shadow);
    transition: all var(--transition-base);
    border: 1px solid var(--glass-border);
    height: 100%;
    display: flex;
    flex-direction: column;
}

.medicine-card:hover {
    transform: translateY(-8px);
    box-shadow: var(--shadow-hover), var(--shadow-glow);
    border-color: rgba(37, 99, 235, 0.3);
    background: rgba(255, 255, 255, 0.85);
}

.medicine-image {
    height: 200px;
    object-fit: cover;
    background: var(--gray-100);
    position: relative;
}

.medicine-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform var(--transition-slow);
}

.medicine-card:hover .medicine-image img {
    transform: scale(1.05);
}

.stock-badge {
    position: absolute;
    top: 12px;
    right: 12px;
    padding: 6px 14px;
    border-radius: var(--radius-full);
    font-size: 0.75rem;
    font-weight: 600;
}

.medicine-info {
    padding: 24px;
    flex: 1;
    display: flex;
    flex-direction: column;
}

.medicine-info h5 {
    font-size: 1.125rem;
    font-weight: 600;
    margin-bottom: 8px;
    color: var(--gray-900);
}

.medicine-info .category-tag {
    display: inline-block;
    background: var(--primary-red-light);
    color: var(--primary-red);
    padding: 4px 12px;
    border-radius: var(--radius-full);
    font-size: 0.75rem;
    font-weight: 500;
    margin-bottom: 12px;
}

.medicine-price {
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--primary-red);
    margin-top: auto;
    margin-bottom: 16px;
}

.medicine-actions {
    display: flex;
    gap: 12px;
}

.medicine-actions .btn {
    flex: 1;
    padding: 12px;
    font-size: 0.875rem;
}

/* Load More Button */
#loadMoreBtn {
    padding: 14px 40px;
    border-radius: var(--radius-full);
    font-weight: 600;
}

/* ============================================
   CONSULTATION SECTION
   ============================================ */
.consultation-section {
    padding: var(--section-padding) 0;
    background: white;
}

.consultation-image {
    position: relative;
}

.consultation-image img {
    border-radius: var(--radius-xl);
    box-shadow: var(--shadow-lg);
}

.consultation-image::after {
    content: '';
    position: absolute;
    bottom: -20px;
    right: -20px;
    width: 150px;
    height: 150px;
    background: var(--primary-red-light);
    border-radius: var(--radius-xl);
    z-index: -1;
}

/* Consultation Form Card */
.consultation-form .card {
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-xl);
    box-shadow: var(--shadow-lg), var(--shadow-glow);
    overflow: hidden;
    background: var(--glass-bg);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
}

.consultation-form .card-body {
    padding: 40px;
}

.consultation-form .card-title {
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--gray-900);
    margin-bottom: 28px;
    display: flex;
    align-items: center;
    gap: 12px;
}

.consultation-form .card-title i {
    color: var(--primary-red);
}

.consultation-form .form-label {
    font-weight: 600;
    color: var(--gray-700);
    margin-bottom: 8px;
}

.consultation-form .form-control,
.consultation-form .form-select {
    padding: 14px 18px;
    border-radius: var(--radius-md);
    border: 2px solid var(--gray-200);
    font-size: 0.9375rem;
    transition: all var(--transition-base);
}

.consultation-form .form-control:focus,
.consultation-form .form-select:focus {
    border-color: var(--primary-red);
    box-shadow: 0 0 0 4px var(--primary-red-glow);
}

/* Time Slots */
.time-slots {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
    gap: 12px;
    margin-top: 12px;
}

.time-slot {
    padding: 12px 16px;
    border: 2px solid var(--gray-200);
    border-radius: var(--radius-md);
    text-align: center;
    cursor: pointer;
    transition: all var(--transition-base);
    background: white;
    font-weight: 500;
    font-size: 0.875rem;
}

.time-slot:hover {
    border-color: var(--primary-red);
    background: var(--primary-red-light);
}

.time-slot.selected {
    background: var(--gradient-primary);
    color: white;
    border-color: var(--primary-red);
    box-shadow: var(--shadow-red);
}

.time-slot.unavailable {
    background: var(--gray-100);
    color: var(--gray-400);
    cursor: not-allowed;
    border-color: var(--gray-200);
}

/* Doctor Cards */
.doctor-card {
    background: var(--glass-bg);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-lg);
    padding: 32px 24px;
    text-align: center;
    transition: all var(--transition-base);
    height: 100%;
    box-shadow: var(--glass-shadow);
}

.doctor-card:hover {
    transform: translateY(-6px);
    box-shadow: var(--shadow-lg), var(--shadow-glow);
    border-color: rgba(37, 99, 235, 0.3);
    background: rgba(255, 255, 255, 0.85);
}

.doctor-avatar {
    width: 100px;
    height: 100px;
    border-radius: 50%;
    margin: 0 auto 20px;
    background: linear-gradient(135deg, var(--primary-light) 0%, rgba(37, 99, 235, 0.1) 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2.5rem;
    color: var(--primary);
    border: 4px solid var(--primary-light);
    transition: all var(--transition-base);
}

.doctor-card:hover .doctor-avatar {
    border-color: var(--primary-accent);
    box-shadow: 0 0 20px rgba(37, 99, 235, 0.3);
}

.doctor-card h6 {
    font-size: 1.125rem;
    font-weight: 700;
    color: var(--gray-900);
    margin-bottom: 8px;
}

.doctor-card .specialization {
    color: var(--primary-red);
    font-weight: 500;
    margin-bottom: 8px;
}

.doctor-card .info {
    color: var(--gray-500);
    font-size: 0.875rem;
}

/* ============================================
   ABOUT SECTION
   ============================================ */
.about-section {
    padding: var(--section-padding) 0;
    background: var(--gray-50);
}

.about-content h2 {
    font-size: 2.5rem;
    margin-bottom: 20px;
}

.about-content .lead {
    margin-bottom: 32px;
}

.about-features {
    display: flex;
    flex-direction: column;
    gap: 24px;
}

.feature-item {
    display: flex;
    align-items: flex-start;
    gap: 20px;
    padding: 20px;
    background: var(--glass-bg);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border-radius: var(--radius-md);
    transition: all var(--transition-base);
    border: 1px solid var(--glass-border);
    box-shadow: var(--glass-shadow);
}

.feature-item:hover {
    transform: translateX(8px);
    box-shadow: var(--shadow-md), var(--shadow-glow);
    border-color: rgba(37, 99, 235, 0.3);
    background: rgba(255, 255, 255, 0.85);
}

.feature-icon {
    width: 56px;
    height: 56px;
    min-width: 56px;
