    text-decoration: none;
    transition: color var(--transition-base);
}

footer a:hover {
    color: white;
}

footer .social-links a {
    width: 40px;
    height: 40px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: rgba(255, 255, 255, 0.1);
    border-radius: 50%;
    margin-right: 12px;
    transition: all var(--transition-base);
}

footer .social-links a:hover {
    background: var(--primary-accent);
    transform: translateY(-3px);
    box-shadow: 0 4px 12px rgba(37, 99, 235, 0.4);
}

/* ============================================
   RESPONSIVE DESIGN
   ============================================ */
@media (max-width: 1200px) {
    .hero-content h1 {
        font-size: 3rem;
    }

    .section-title {
        font-size: 2.25rem;
    }
}

@media (max-width: 992px) {
    :root {
        --section-padding: 80px;
    }

    .hero-content h1 {
        font-size: 2.5rem;
    }

    .hero-stats {
        gap: 24px;
    }

    .stat-item h3 {
        font-size: 2rem;
    }

    .feature-highlights {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 768px) {
    :root {
        --section-padding: 60px;
    }

    .main-content {
        padding-top: 70px;
    }

    .hero-content h1 {
        font-size: 2.25rem;
        text-align: center;
    }

    .hero-content .lead {
        text-align: center;
    }

    .hero-buttons {
        justify-content: center;
    }

    .hero-stats {
        justify-content: center;
    }

    .hero-image::before {
        display: none;
    }

    .section-title {
        font-size: 2rem;
    }

    .service-card {
        padding: 28px 20px;
    }

    .chat-widget {
        width: 90%;
        right: 5%;
        left: 5%;
    }

    .medicine-actions {
        flex-direction: column;
    }

    .consultation-image::after {
        display: none;
    }

    .side-panel {
        width: 100%;
        right: -100%;
    }

    .control-buttons .btn {
        width: 50px;
        height: 50px;
        margin: 0 6px;
    }
}

@media (max-width: 576px) {
    .hero-content h1 {
        font-size: 1.875rem;
    }

    .hero-buttons .btn {
        width: 100%;
    }

    .hero-stats {
        flex-direction: column;
        gap: 20px;
    }

    .section-title {
        font-size: 1.75rem;
    }

    .feature-highlights {
        grid-template-columns: 1fr;
    }

    .time-slots {
        grid-template-columns: repeat(2, 1fr);
    }

    .consultation-form .card-body {
        padding: 24px;
    }

    .modal-body {
        padding: 20px;
    }
}

/* ============================================
   ANIMATIONS
   ============================================ */
@keyframes fadeInUp {
    from {
        opacity: 0;
        transform: translateY(30px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes pulse {
    0%, 100% {
        transform: scale(1);
    }
    50% {
        transform: scale(1.05);
    }
}

.fade-in-up {
    animation: fadeInUp 0.6s ease forwards;
}

.pulse {
    animation: pulse 2s infinite;
}

/* Smooth scroll indicator */
.scroll-indicator {
    position: absolute;
    bottom: 30px;
    left: 50%;
    transform: translateX(-50%);
    animation: bounce 2s infinite;
}

@keyframes bounce {
    0%, 20%, 50%, 80%, 100% {
        transform: translateX(-50%) translateY(0);
    }
    40% {
        transform: translateX(-50%) translateY(-10px);
    }
    60% {
        transform: translateX(-50%) translateY(-5px);
    }
}

