        doctor = User.query.filter_by(id=user_data['sub'], role="doctor").first()
        if not doctor:
            return jsonify({"error": "Doctor not found"}), 404

        # Find appointment
        appointment = Appointment.query.filter_by(id=appointment_id, doctor_id=doctor.id).first()
