    // ============ UTILITY FUNCTIONS ============

    getStatusColor(status) {
        const colors = {
            'pending': 'warning',
            'confirmed': 'info',
            'processing': 'info',
            'out_for_delivery': 'primary',
            'delivered': 'success',
            'cancelled': 'danger',
            'scheduled': 'info',
            'ongoing': 'warning',
            'completed': 'success'
        };
        return colors[status] || 'secondary';
    }

    getApprovalStatusColor(status) {
        const colors = {
            'pending': 'warning',
            'approved': 'success',
            'declined': 'danger'
        };
        return colors[status] || 'secondary';
    }

    getRoleColor(role) {
        const colors = {
            'admin': 'danger',
            'doctor': 'success',
            'patient': 'primary'
        };
        return colors[role] || 'secondary';
    }

