def list_users():
    """List all users with pagination"""
    try:
        current_admin = get_current_admin()
        if not current_admin:
            return jsonify({"error": "Admin access required"}), 403

        # Get query parameters
        role = request.args.get('role')
        search = request.args.get('search')
        limit = int(request.args.get('limit', 20))
        offset = int(request.args.get('offset', 0))

        # Build query
        query = User.query

        if role:
            query = query.filter_by(role=role)

        if search:
            search_term = f"%{search}%"
            query = query.filter(
                db.or_(
                    User.name.ilike(search_term),
                    User.email.ilike(search_term),
                    User.phone.ilike(search_term)
                )
            )

        total_count = query.count()
        users = query.order_by(User.created_at.desc()).offset(offset).limit(limit).all()

        user_list = []
        for user in users:
            # Get user statistics
            if user.role == "patient":
                appointments_count = Appointment.query.filter_by(user_id=user.id).count()
                orders_count = Order.query.filter_by(user_id=user.id).count()
            elif user.role == "doctor":
                appointments_count = Appointment.query.filter_by(doctor_id=user.id).count()
                orders_count = 0
            else:
                appointments_count = 0
                orders_count = 0

            user_list.append({
                "id": user.id,
                "name": user.name,
                "email": user.email,
                "phone": user.phone,
                "role": user.role,
                "created_at": user.created_at.isoformat(),
                "appointments_count": appointments_count,
                "orders_count": orders_count
            })

        return jsonify({
            "success": True,
            "users": user_list,
            "total_count": total_count,
            "offset": offset,
            "limit": limit
        })

    except Exception as e:
        logging.error(f"List users error: {e}")
