    getOrderStatusColor(status) {
        const colors = {
            'pending': 'warning',
            'confirmed': 'info',
            'processing': 'info',
            'out_for_delivery': 'primary',
            'delivered': 'success',
            'cancelled': 'danger'
        };
        return colors[status] || 'secondary';
    }

    getAppointmentStatusColor(status) {
        const colors = {
            'scheduled': 'primary',
            'ongoing': 'success',
            'completed': 'success',
            'cancelled': 'danger'
        };
        return colors[status] || 'secondary';
    }

    // ============ EVENT LISTENERS ============

    initializeEventListeners() {
        // Login form
        document.addEventListener('submit', async (e) => {
            if (e.target.id === 'loginForm') {
                e.preventDefault();
                const email = document.getElementById('loginEmail').value;
                const password = document.getElementById('loginPassword').value;
                await this.login(email, password);
            }

            if (e.target.id === 'registerForm') {
                e.preventDefault();
                const formData = new FormData(e.target);

                // Validate password confirmation
                if (formData.get('password') !== formData.get('confirmPassword')) {
                    this.showError('Passwords do not match');
                    return;
                }

                const userData = {
                    name: formData.get('name'),
                    email: formData.get('email'),
                    phone: formData.get('phone'),
                    password: formData.get('password')
                };

                await this.register(userData);
            }

            if (e.target.id === 'consultationForm') {
                e.preventDefault();
                const formData = new FormData(e.target);
                await this.bookAppointment(formData);
            }
        });

        // Search functionality
        document.addEventListener('keypress', (e) => {
            if (e.target.id === 'medicineSearch' && e.key === 'Enter') {
                this.searchMedicines(e.target.value);
            }
        });

        // Date change for time slots
        document.addEventListener('change', (e) => {
            if (e.target.id === 'consultationDate') {
                this.loadTimeSlots();
            }
            if (e.target.id === 'doctorSelect') {
                this.loadTimeSlots();
            }
        });
    }

    // ============ UI HELPER METHODS ============

    showLoading() {
        const spinner = document.getElementById('loadingSpinner');
        if (spinner) spinner.style.display = 'flex';
    }

    hideLoading() {
        const spinner = document.getElementById('loadingSpinner');
        if (spinner) spinner.style.display = 'none';
    }

    showSuccess(message) {
        this.showAlert(message, 'success');
    }

    showError(message) {
        this.showAlert(message, 'danger');
    }

    showAlert(message, type) {
        // Remove existing alerts
        document.querySelectorAll('.app-alert').forEach(alert => alert.remove());

        const alertHtml = `
            <div class="alert alert-${type} alert-dismissible fade show app-alert" role="alert" style="position: fixed; top: 100px; right: 20px; z-index: 9999; min-width: 300px;">
                ${message}
                <button type="button" class="btn-close" data-bs-dismiss="alert"></button>
            </div>
        `;

        document.body.insertAdjacentHTML('beforeend', alertHtml);

        // Auto dismiss after 5 seconds
        setTimeout(() => {
            const alert = document.querySelector('.app-alert');
            if (alert) {
                bootstrap.Alert.getOrCreateInstance(alert).close();
            }
        }, 5000);
    }

    hideAllModals() {
        document.querySelectorAll('.modal.show').forEach(modal => {
            const modalInstance = bootstrap.Modal.getInstance(modal);
            if (modalInstance) {
                modalInstance.hide();
            }
        });
    }

    showLogin() {
        const modal = new bootstrap.Modal(document.getElementById('loginModal'));
        modal.show();
    }

    showRegister() {
        this.hideAllModals();
        const modal = new bootstrap.Modal(document.getElementById('registerModal'));
        modal.show();
    }

    showCart() {
        this.displayCartItems();
        const modal = new bootstrap.Modal(document.getElementById('cartModal'));
        modal.show();
    }
}

